25	/**
26	 * Load and store Android Manifest attributes specification
27	 */
28	public class ManifestAttributes {
29		private static final Logger LOG = LoggerFactory.getLogger(ManifestAttributes.class);
30	
31		private static final String ATTR_XML = "/android/attrs.xml";
32		private static final String MANIFEST_ATTR_XML = "/android/attrs_manifest.xml";
33	
34		private enum MAttrType {
35			ENUM, FLAG
36		}
37	
38		private static class MAttr {
39			private final MAttrType type;
40			private final Map<Long, String> values = new LinkedHashMap<>();
41	
42			public MAttr(MAttrType type) {
43				this.type = type;
44			}
45	
46			public MAttrType getType() {
47				return type;
48			}
49	
50			public Map<Long, String> getValues() {
51				return values;
52			}
53	
54			public void addValue(long key, String value) {
55				values.put(key, value);
56			}
57	
58			@Override
59			public String toString() {
60				return "[" + type + ", " + values + ']';
61			}
62		}
63	
64		private final IJadxSecurity security;
65	
66		/**
67		 * Map containing default Android resource attribute definitions.
68		 * Keys are Android attribute names (e.g., "android:layout_width"),
69		 * and values are their corresponding {@link MAttr} objects.
70		 */
71		private final Map<String, MAttr> attrMap = new HashMap<>();
72		private final Map<String, MAttr> appAttrMap = new HashMap<>();
73	
74		public ManifestAttributes(IJadxSecurity security) {
75			this.security = security;
76			parseAll();
77		}
78	
79		private void parseAll() {
80			parse(loadXML(ATTR_XML));
81			parse(loadXML(MANIFEST_ATTR_XML));
82			LOG.debug("Loaded android attributes count: {}", attrMap.size());
83		}
84	
85		private Document loadXML(String xml) {
86			Document doc;
87			try (InputStream xmlStream = ManifestAttributes.class.getResourceAsStream(xml)) {
88				if (xmlStream == null) {
89					throw new JadxRuntimeException(xml + " not found in classpath");
90				}
91				doc = security.parseXml(xmlStream);
92			} catch (Exception e) {
93				throw new JadxRuntimeException("Xml load error, file: " + xml, e);
94			}
95			return doc;
96		}
97	
98		private void parse(Document doc) {
99			NodeList nodeList = doc.getChildNodes();
100			for (int count = 0; count < nodeList.getLength(); count++) {
101				Node node = nodeList.item(count);
102				if (node.getNodeType() == Node.ELEMENT_NODE
103						&& node.hasChildNodes()) {
104					parseAttrList(node.getChildNodes());
105				}
106			}
107		}
108	
109		private void parseAttrList(NodeList nodeList) {
110			for (int count = 0; count < nodeList.getLength(); count++) {
111				Node tempNode = nodeList.item(count);
112				if (tempNode.getNodeType() == Node.ELEMENT_NODE
113						&& tempNode.hasAttributes()
114						&& tempNode.hasChildNodes()) {
115					String name = null;
116					NamedNodeMap nodeMap = tempNode.getAttributes();
117					for (int i = 0; i < nodeMap.getLength(); i++) {
118						Node node = nodeMap.item(i);
119						if (node.getNodeName().equals("name")) {
120							name = node.getNodeValue();
121							break;
122						}
123					}
124					if (name != null && tempNode.getNodeName().equals("attr")) {
125						parseValues(name, tempNode.getChildNodes());
126					} else {
127						parseAttrList(tempNode.getChildNodes());
128					}
129				}
130			}
131		}
132	
133		private void parseValues(String name, NodeList nodeList) {
134			MAttr attr = null;
135			for (int count = 0; count < nodeList.getLength(); count++) {
136				Node tempNode = nodeList.item(count);
137				if (tempNode.getNodeType() == Node.ELEMENT_NODE
138						&& tempNode.hasAttributes()) {
139					if (attr == null) {
140						if (tempNode.getNodeName().equals("enum")) {
141							attr = new MAttr(MAttrType.ENUM);
142						} else if (tempNode.getNodeName().equals("flag")) {
143							attr = new MAttr(MAttrType.FLAG);
144						}
145						if (attr == null) {
146							return;
147						}
148						attrMap.put("android:" + name, attr);
149					}
150					NamedNodeMap attributes = tempNode.getAttributes();
151					Node nameNode = attributes.getNamedItem("name");
152					if (nameNode != null) {
153						Node valueNode = attributes.getNamedItem("value");
154						if (valueNode != null) {
155							try {
156								long key;
157								String nodeValue = valueNode.getNodeValue();
158								if (nodeValue.startsWith("0x")) {
159									nodeValue = nodeValue.substring(2);
160									key = Long.parseLong(nodeValue, 16);
161								} else {
162									key = Long.parseLong(nodeValue);
163								}
164								attr.addValue(key, nameNode.getNodeValue());
165							} catch (NumberFormatException e) {
166								LOG.debug("Failed parse manifest number", e);
167							}
168						}
169					}
170				}
171			}
172		}
173	
174		public String decode(String attrName, long value) {
175			MAttr attr = attrMap.get(attrName);
176			if (attr == null) {
177				if (attrName.contains(":")) {
178					attrName = attrName.split(":", 2)[1];
179				}
180				attr = appAttrMap.get(attrName);
181				if (attr == null) {
182					return null;
183				}
184			}
185	
186			Map<Long, String> attrValuesMap = attr.getValues();
187			if (attr.getType() == MAttrType.ENUM) {
188				return attrValuesMap.get(value);
189			} else if (attr.getType() == MAttrType.FLAG) {
190				List<String> flagList = new ArrayList<>();
191				List<Long> attrKeys = new ArrayList<>(attrValuesMap.keySet());
192				attrKeys.sort((a, b) -> Long.compare(b, a)); // sort descending
193				for (Long key : attrKeys) {
194					String attrValue = attrValuesMap.get(key);
195					if (value == key) {
196						flagList.add(attrValue);
197						break;
198					} else if ((key != 0) && ((value & key) == key)) {
199						flagList.add(attrValue);
200						value ^= key;
201					}
202				}
203				return String.join("|", flagList);
204			}
205			return null;
206		}
207	
208		public void updateAttributes(IResTableParser parser) {
209			appAttrMap.clear();
210	
211			ResourceStorage resStorage = parser.getResStorage();
212			ValuesParser vp = new ValuesParser(parser.getStrings(), resStorage.getResourcesNames());
213	
214			for (ResourceEntry ri : resStorage.getResources()) {
215				if (ri.getProtoValue() != null) {
216					// Aapt proto decoder resolves attributes by itself.
217					continue;
218				}
219	
220				if (ri.getTypeName().equals("attr") && ri.getNamedValues().size() > 1) {
221					RawNamedValue first = ri.getNamedValues().get(0);
222					MAttrType attrTyp;
223					int attrTypeVal = first.getRawValue().getData() & 0xff0000;
224					if (attrTypeVal == ValuesParser.ATTR_TYPE_FLAGS) {
225						attrTyp = MAttrType.FLAG;
226					} else if (attrTypeVal == ValuesParser.ATTR_TYPE_ENUM) {
227						attrTyp = MAttrType.ENUM;
228					} else {
229						continue;
230					}
231					MAttr attr = new MAttr(attrTyp);
232					for (int i = 1; i < ri.getNamedValues().size(); i++) {
233						RawNamedValue rv = ri.getNamedValues().get(i);
234						String value = vp.decodeNameRef(rv.getNameRef());
235						attr.addValue(rv.getRawValue().getData(), value.startsWith("id.") ? value.substring(3) : value);
236					}
237					appAttrMap.put(ri.getKeyName(), attr);
238				}
239			}
240		}
241	}
