15	
16	public class ValuesParser extends ParserConstants {
17		private static final Logger LOG = LoggerFactory.getLogger(ValuesParser.class);
18	
19		private final BinaryXMLStrings strings;
20		private final Map<Integer, String> resMap;
21	
22		public ValuesParser(BinaryXMLStrings strings, Map<Integer, String> resMap) {
23			this.strings = strings;
24			this.resMap = resMap;
25		}
26	
27		@Nullable
28		public String getSimpleValueString(ResourceEntry ri) {
29			ProtoValue protoValue = ri.getProtoValue();
30			if (protoValue != null) {
31				return protoValue.getValue();
32			}
33			RawValue simpleValue = ri.getSimpleValue();
34			if (simpleValue == null) {
35				return null;
36			}
37			return decodeValue(simpleValue);
38		}
39	
40		@Nullable
41		public String getValueString(ResourceEntry ri) {
42			ProtoValue protoValue = ri.getProtoValue();
43			if (protoValue != null) {
44				if (protoValue.getValue() != null) {
45					return protoValue.getValue();
46				}
47				List<ProtoValue> values = protoValue.getNamedValues();
48				List<String> strList = new ArrayList<>(values.size());
49				for (ProtoValue value : values) {
50					if (value.getName() == null) {
51						strList.add(value.getValue());
52					} else {
53						strList.add(value.getName() + '=' + value.getValue());
54					}
55				}
56				return strList.toString();
57			}
58			RawValue simpleValue = ri.getSimpleValue();
59			if (simpleValue != null) {
60				return decodeValue(simpleValue);
61			}
62			List<RawNamedValue> namedValues = ri.getNamedValues();
63			List<String> strList = new ArrayList<>(namedValues.size());
64			for (RawNamedValue value : namedValues) {
65				String nameStr = decodeNameRef(value.getNameRef());
66				String valueStr = decodeValue(value.getRawValue());
67				if (nameStr == null) {
68					strList.add(valueStr);
69				} else {
70					strList.add(nameStr + '=' + valueStr);
71				}
72			}
73			return strList.toString();
74		}
75	
76		@Nullable
77		public String decodeValue(RawValue value) {
78			int dataType = value.getDataType();
79			int data = value.getData();
80			return decodeValue(dataType, data);
81		}
82	
83		@Nullable
84		public String decodeValue(int dataType, int data) {
85			switch (dataType) {
86				case TYPE_NULL:
87					return null;
88				case TYPE_STRING:
89					return strings.get(data);
90				case TYPE_INT_DEC:
91					return Integer.toString(data);
92				case TYPE_INT_HEX:
93					return "0x" + Integer.toHexString(data);
94				case TYPE_INT_BOOLEAN:
95					return data == 0 ? "false" : "true";
96				case TYPE_FLOAT:
97					return XmlGenUtils.floatToString(Float.intBitsToFloat(data));
98				case TYPE_INT_COLOR_ARGB8:
99					return String.format("#%08x", data);
100				case TYPE_INT_COLOR_RGB8:
101					return String.format("#%06x", data & 0xFFFFFF);
102				case TYPE_INT_COLOR_ARGB4:
103					return String.format("#%04x", data & 0xFFFF);
104				case TYPE_INT_COLOR_RGB4:
105					return String.format("#%03x", data & 0xFFF);
106	
107				case TYPE_DYNAMIC_REFERENCE:
108				case TYPE_REFERENCE: {
109					String ri = resMap.get(data);
110					if (ri == null) {
111						String androidRi = AndroidResourcesMap.getResName(data);
112						if (androidRi != null) {
113							return "@android:" + androidRi;
114						}
115						if (data == 0) {
116							return "0";
117						}
118						return "?unknown_ref: " + Integer.toHexString(data);
119					}
120					return '@' + ri;
121				}
122	
123				case TYPE_ATTRIBUTE: {
124					String ri = resMap.get(data);
125					if (ri == null) {
126						String androidRi = AndroidResourcesMap.getResName(data);
127						if (androidRi != null) {
128							return "?android:" + androidRi;
129						}
130						return "?unknown_attr_ref: " + Integer.toHexString(data);
131					}
132					return '?' + ri;
133				}
134	
135				case TYPE_DIMENSION:
136					return XmlGenUtils.decodeComplex(data, false);
137				case TYPE_FRACTION:
138					return XmlGenUtils.decodeComplex(data, true);
139				case TYPE_DYNAMIC_ATTRIBUTE:
140					LOG.warn("Data type TYPE_DYNAMIC_ATTRIBUTE not yet supported: {}", data);
141					return "  TYPE_DYNAMIC_ATTRIBUTE: " + data;
142	
143				default:
144					LOG.warn("Unknown data type: 0x{} {}", Integer.toHexString(dataType), data);
145					return "  ?0x" + Integer.toHexString(dataType) + ' ' + data;
146			}
147		}
148	
149		public String decodeNameRef(int nameRef) {
150			int ref = nameRef;
151			if (isResInternalId(nameRef)) {
152				ref = nameRef & ATTR_TYPE_ANY;
153				if (ref == 0) {
154					return null;
155				}
156			}
157			String ri = resMap.get(ref);
158			if (ri != null) {
159				return ri.replace('/', '.');
160			} else {
161				String androidRi = AndroidResourcesMap.getResName(ref);
162				if (androidRi != null) {
163					return "android:" + androidRi.replace('/', '.');
164				}
165			}
166			return "?0x" + Integer.toHexString(nameRef);
167		}
168	}
