64		public static String smaliNameToJavaName(String descString) {
65			if (descString.isEmpty()) {
66				return descString;
67			}
68	
69			String javaName;
70			switch (descString.charAt(0)) {
71				case 'V':
72					javaName = "void";
73					break;
74				case 'Z':
75					javaName = "boolean";
76					break;
77				case 'C':
78					javaName = "char";
79					break;
80				case 'B':
81					javaName = "byte";
82					break;
83				case 'S':
84					javaName = "short";
85					break;
86				case 'I':
87					javaName = "int";
88					break;
89				case 'F':
90					javaName = "float";
91					break;
92				case 'J':
93					javaName = "long";
94					break;
95				case 'D':
96					javaName = "double";
97					break;
98				case 'L':
99					javaName = cleanObjectNameWithInnerClass(descString);
100					break;
101				case '[':
102					javaName = String.format("%s[]", smaliNameToJavaName(descString.substring(1, descString.length())));
103					break;
104				default:
105					javaName = descString;
106					break;
107			}
108			return javaName;
109		}
