306		private static void filterRecursive(Throwable th) {
307			try {
308				filter(th);
309			} catch (Exception e) {
310				// ignore filter exceptions
311			}
312			Throwable cause = th.getCause();
313			if (cause != null) {
314				filterRecursive(cause);
315			}
316		}
