60		private void processCodePoint(int codePoint, StringBuilder res) {
61			String str = getSpecialStringForCodePoint(codePoint);
62			if (str != null) {
63				res.append(str);
64				return;
65			}
66			if (isEscapeNeededForCodePoint(codePoint)) {
67				res.append("\\u").append(String.format("%04x", codePoint));
68			} else {
69				res.appendCodePoint(codePoint);
70			}
71		}
