73		private boolean isEscapeNeededForCodePoint(int codePoint) {
74			if (codePoint < 32) {
75				return true;
76			}
77			if (codePoint < 127) {
78				return false;
79			}
80			if (escapeUnicode) {
81				return true;
82			}
83			return !NameMapper.isPrintableCodePoint(codePoint);
84		}
