92			}
93			String str = getSpecialStringForCodePoint(c);
94			if (str != null) {
95				return '\'' + str + '\'';
96			}
97			if (c >= 127 && escapeUnicode) {
98				return String.format("'\\u%04x'", (int) c);
99			}
100			if (NameMapper.isPrintableChar(c)) {
101				return "'" + c + '\'';
102			}
103			String intStr = Integer.toString(c);
104			return explicitCast ? "(char) " + intStr : intStr;
105		}
