			@Override
			public void write(int b) {
				char c = (char) b;
				switch (c) {
					case '\n':
						code.startLine();
						break;

					case '\r':
						// ignore
						break;

					default:
						code.add(c);
						break;
				}
			}
		};
		try (PrintWriter pw = new PrintWriter(w, true, StandardCharsets.UTF_8)) {
			filterRecursive(throwable);
			throwable.printStackTrace(pw);
			pw.flush();
